def src(key,pattern=None,manifest_alias=None):
 if manifest_alias:
  m=next(x for x in manifest['sources'] if x['alias']==manifest_alias)
  p=Path(m['source']['text_path']);extra={'retained_pdf_path':m['source']['local_path'],'manifest_pdf_sha256':m['source']['sha256'],'pdf_locally_present':(ROOT/m['source']['local_path']).exists(),'url':m['source']['url'],'role':'held retained primary-source text extraction; raw PDF not independently inspected in this worker'}
 else:
  paths=list((ROOT/'jobs/app-executive-orders/output/texts').glob(pattern));assert len(paths)==1,(key,paths)
  p=paths[0].relative_to(ROOT);extra={'role':'held APP transcription, not original; identity must be reconciled with dossier/source registry'}
 b=(ROOT/p).read_bytes();sources[key]={'path':str(p),'sha256':hash_(b),**extra};return b.decode('utf-8')
def excerpt(key,source,start,end=None):
 t=(ROOT/sources[source]['path']).read_text();a=t.index(start) if isinstance(start,str) else start
 if end is None:b=t.find('\n\n',a);b=len(t) if b<0 else b
 elif isinstance(end,str):b=t.index(end,a)
 else:b=end
 q=t[a:b];excerpts[key]={'source':source,'char_start':a,'char_end':b,'span_convention':'Unicode codepoints, zero-based, end-exclusive','excerpt':q,'excerpt_sha256':hash_(q.encode())};return key
def prop(i,text,refs,limits,required,category='conditional legal/research proposition'):
 props.append({'id':i,'category':category,'proposition':text,'evidence_refs':refs,'exclusions_and_counterexamples':limits,'individual_evidence_required':required,'status':'research-only; not a lifecycle claim or adopted rule'})
